FUNCTION_BLOCK FB
VAR_INPUT
    mode            : INT;
    resetBtn        : BOOL;
    scanSeconds     : REAL;
    tempSP          : REAL;
    tempPV          : REAL;
    flowPV          : REAL;
    manualFlowSP    : REAL;
    manualValve     : REAL;
END_VAR

VAR_OUTPUT
    flowSP          : REAL;
    valveCommand    : REAL;
    fault           : BOOL;
    normalMode      : BOOL;
END_VAR

VAR
    prevMode            : INT;
    prevResetBtn        : BOOL;
    prevFlowSP          : REAL;
    prevValveCommand    : REAL;
    iT                  : REAL;
    iF                  : REAL;
    initDone            : BOOL;
    eT                  : REAL;
    eF                  : REAL;
    risingReset         : BOOL;
END_VAR

VAR CONSTANT
    KpT             : REAL := 1.0;
    KpF             : REAL := 2.0;
    KiT             : REAL := 0.2;
    KiF             : REAL := 0.5;
    MIN_FLOW_SP     : REAL := 0.0;
    MAX_FLOW_SP     : REAL := 50.0;
    MIN_VALVE       : REAL := 0.0;
    MAX_VALVE       : REAL := 100.0;
END_VAR

risingReset := resetBtn AND NOT prevResetBtn;
fault := (mode < 0) OR (mode > 2) OR (scanSeconds <= 0.0) OR (scanSeconds > 10.0);

IF NOT initDone THEN
    initDone := TRUE;
    flowSP := manualFlowSP;
    valveCommand := manualValve;
    iT := flowSP - KpT * (tempSP - tempPV);
    iF := valveCommand - KpF * (flowSP - flowPV);
    normalMode := FALSE;
    prevMode := mode;
ELSE
    IF fault OR risingReset THEN
        flowSP := manualFlowSP;
        valveCommand := manualValve;
        iT := flowSP - KpT * (tempSP - tempPV);
        iF := valveCommand - KpF * (flowSP - flowPV);
        normalMode := FALSE;
        prevMode := mode;
    ELSIF mode <> prevMode THEN
        valveCommand := prevValveCommand;
        IF mode = 2 THEN
            flowSP := prevFlowSP;
        ELSE
            flowSP := manualFlowSP;
        END_IF
        iT := flowSP - KpT * (tempSP - tempPV);
        iF := valveCommand - KpF * (flowSP - flowPV);
        normalMode := FALSE;
        prevMode := mode;
    ELSE
        normalMode := TRUE;
        IF mode = 0 THEN
            flowSP := manualFlowSP;
            valveCommand := manualValve;
            iT := flowSP - KpT * (tempSP - tempPV);
            iF := valveCommand - KpF * (flowSP - flowPV);
        ELSIF mode = 1 THEN
            flowSP := manualFlowSP;
            iT := flowSP - KpT * (tempSP - tempPV);
            eF := flowSP - flowPV;
            iF := iF + KiF * eF * scanSeconds;
            valveCommand := LIMIT(MIN_VALVE, KpF * eF + iF, MAX_VALVE);
            iF := valveCommand - KpF * eF;
        ELSIF mode = 2 THEN
            eT := tempSP - tempPV;
            iT := iT + KiT * eT * scanSeconds;
            flowSP := LIMIT(MIN_FLOW_SP, KpT * eT + iT, MAX_FLOW_SP);
            iT := flowSP - KpT * eT;
            eF := flowSP - flowPV;
            iF := iF + KiF * eF * scanSeconds;
            valveCommand := LIMIT(MIN_VALVE, KpF * eF + iF, MAX_VALVE);
            iF := valveCommand - KpF * eF;
        ELSE
            flowSP := manualFlowSP;
            valveCommand := manualValve;
            iT := flowSP - KpT * (tempSP - tempPV);
            iF := valveCommand - KpF * (flowSP - flowPV);
        END_IF
        prevMode := mode;
    END_IF
END_IF

flowSP := LIMIT(MIN_FLOW_SP, flowSP, MAX_FLOW_SP);
valveCommand := LIMIT(MIN_VALVE, valveCommand, MAX_VALVE);

prevResetBtn := resetBtn;
prevFlowSP := flowSP;
prevValveCommand := valveCommand;

END_FUNCTION_BLOCK
